"""One center trial with oracle geometry; not learned-policy evaluation."""
from pathlib import Path
import os,sys,json,tempfile,subprocess,hashlib
SOURCE='"""Test a new teacher using the installed Isaac Lab pose convention. No training or dataset overwrite."""\nfrom __future__ import annotations\nimport argparse\nimport json\nimport hashlib\nfrom pathlib import Path\nfrom isaaclab.app import AppLauncher\n\np = argparse.ArgumentParser(description=__doc__)\np.add_argument(\'--instruction\', required=True, choices=[\'pick up the cube\', \'move above the cube\'])\np.add_argument(\'--dataset\', default=\'/workspace/step3/data/lift_robomimic_language.hdf5\')\np.add_argument(\'--demo\', default=\'demo_0\')\np.add_argument(\'--task\', default=\'IsaacContrib-Lift-Cube-Franka-IK-Rel-Visuomotor\')\np.add_argument(\'--output-dir\', required=True)\np.add_argument(\'--seed\', type=int, default=2058)\np.add_argument(\'--horizon\', type=int, default=600)\np.add_argument(\'--dx-mm\',type=float,default=0.)\np.add_argument(\'--dy-mm\',type=float,default=0.)\nAppLauncher.add_app_launcher_args(p)\nargs = p.parse_args()\napp = AppLauncher(args, headless=True, enable_cameras=True).app\n\nfrom smoke_utils import capture_obs, export_episode\nimport gymnasium as gym\nimport h5py\nimport numpy as np\nimport torch\nfrom PIL import Image\nimport isaaclab_tasks\nfrom isaaclab_tasks.utils import parse_env_cfg\nfrom isaaclab.utils.math import subtract_frame_transforms, compute_pose_error\n\n\ndef tensor(x):\n    return x if torch.is_tensor(x) else x.torch\n\n\ndef array(x):\n    return tensor(x).detach().cpu().numpy().copy()\n\n\ndef read_state(group):\n    return {k: read_state(v) if isinstance(v, h5py.Group) else\n            torch.as_tensor(v[()], device=args.device) for k, v in group.items()}\n\n\ndef bounded(v, limit):\n    return v * torch.clamp(limit / torch.linalg.vector_norm(v, dim=-1, keepdim=True).clamp_min(1e-8), max=1.)\n\n\ndef load_cube_estimator(device):\n    from torch import nn\n    from torchvision.models import resnet18\n    path=Path(\'/workspace/step4/spatial_cube_oracle30_refit_n1yvrn5i/candidate.pt\')\n    ck=torch.load(path,map_location=\'cpu\',weights_only=False)\n    assert ck[\'format\']==\'spatial_cube_estimator_v1\'\n    net=resnet18(weights=None)\n    encoder=nn.Sequential(*list(net.children())[:6],nn.AdaptiveAvgPool2d((5,5))).to(device).eval()\n    encoder.load_state_dict(ck[\'encoder_state\'],strict=True)\n    head=nn.Sequential(nn.Linear(ck[\'input_dim\'],256),nn.GELU(),nn.Linear(256,64),nn.GELU(),nn.Linear(64,3)).to(device).eval()\n    head.load_state_dict(ck[\'head_state\'],strict=True)\n    fm=ck[\'feature_mean\'].to(device);fs=ck[\'feature_scale\'].to(device)\n    ym=ck[\'target_mean\'].to(device);ys=float(ck[\'target_scale\'])\n    mean=torch.tensor([.485,.456,.406],device=device)[None,:,None,None]\n    std=torch.tensor([.229,.224,.225],device=device)[None,:,None,None]\n    def predict(captured):\n        q=captured[\'eef_quat\'].copy()\n        if q[3]<0:q=-q\n        state=np.concatenate([captured[\'eef_pos\'],q,captured[\'gripper_pos\']])\n        with torch.inference_mode():\n            maps=[]\n            for key in (\'table_cam\',\'wrist_cam\'):\n                im=torch.tensor(captured[key],device=device).permute(2,0,1).float()[None]/255\n                maps.append(encoder((im-mean)/std).flatten(1))\n            feature=torch.cat(maps+[torch.tensor(state,device=device,dtype=torch.float32)[None]],dim=1)\n            relative=head((feature-fm)/fs)*ys+ym\n        result=captured[\'eef_pos\']+relative[0].cpu().numpy()\n        assert np.isfinite(result).all()\n        return result\n    return predict\n\ndef remote_asset_fields(root):\n    seen = set()\n    def walk(obj, path):\n        if obj is None or isinstance(obj, (str, bytes, int, float, bool, type)) or callable(obj):\n            return\n        if id(obj) in seen:\n            return\n        seen.add(id(obj))\n        if isinstance(obj, dict):\n            fields = list(obj.items())\n        elif isinstance(obj, (list, tuple)):\n            for index, value in enumerate(obj):\n                yield from walk(value, path+\'[\'+str(index)+\']\')\n            return\n        elif hasattr(obj, \'__dict__\'):\n            fields = list(vars(obj).items())\n        else:\n            return\n        for name, value in fields:\n            field_path = path+\'.\'+str(name)\n            if name in (\'usd_path\', \'texture_file\') and isinstance(value, str) and value.startswith((\'https://\', \'http://\')):\n                yield obj, name, value, field_path\n            else:\n                yield from walk(value, field_path)\n    return list(walk(root, \'cfg\'))\n\n\ndef localize_scene_assets(cfg, report_dir):\n    import hashlib, json, threading\n    from pathlib import Path\n    from urllib.parse import urljoin, urlsplit\n    import omni.client\n    from pxr import Sdf, UsdUtils\n\n    cache = Path(\'/workspace/step4/local_scene_assets_v1\')\n    cache.mkdir(parents=True, exist_ok=True)\n    mapped, manifest = {}, []\n\n    def localize(url):\n        if url in mapped:\n            return mapped[url]\n        parsed = urlsplit(url)\n        if parsed.scheme not in (\'http\', \'https\'):\n            raise RuntimeError(\'Unsupported asset URL: \'+url)\n        suffix = Path(parsed.path).suffix.lower()\n        if suffix == \'.mdl\':\n            raise RuntimeError(\'External MDL dependency needs packaging: \'+url)\n        key = hashlib.sha256(url.encode()).hexdigest()\n        raw = cache / (key+\'.source\'+suffix)\n        dest = cache / (key+suffix)\n        if not raw.exists():\n            event, answer = threading.Event(), []\n            def callback(result, version, content):\n                try:\n                    answer.append((result, bytes(content) if result == omni.client.Result.OK else b\'\'))\n                except Exception as exc:\n                    answer.append((str(exc), b\'\'))\n                finally:\n                    event.set()\n            request = omni.client.read_file_with_callback(url, callback)\n            if not event.wait(60):\n                request.stop()\n                raise RuntimeError(\'Asset download timeout: \'+url)\n            result, data = answer[0]\n            if result != omni.client.Result.OK or not data:\n                raise RuntimeError(\'Asset download failed: \'+url+\' \'+str(result))\n            temp = raw.with_name(raw.name+\'.part\')\n            temp.write_bytes(data)\n            temp.replace(raw)\n        mapped[url] = str(dest)\n        dependencies = []\n        if suffix in (\'.usd\', \'.usda\', \'.usdc\'):\n            layer = Sdf.Layer.FindOrOpen(str(raw))\n            if not layer:\n                raise RuntimeError(\'Cannot open local USD: \'+str(raw))\n            def rewrite(asset):\n                if not asset:\n                    return asset\n                # Isaac\'s bundled MDL modules are resolved by its normal search path.\n                if asset.endswith(\'.mdl\') and \'/\' not in asset and \'\\\\\' not in asset:\n                    return asset\n                if \'<\' in asset or \'[\' in asset:\n                    raise RuntimeError(\'Asset template/package path needs packaging: \'+asset)\n                dependency = urljoin(url, asset)\n                dependencies.append(dependency)\n                return localize(dependency)\n            # Work on an anonymous copy; downloaded source bytes remain unchanged.\n            copy = Sdf.Layer.CreateAnonymous(\'.usda\')\n            copy.TransferContent(layer)\n            UsdUtils.ModifyAssetPaths(copy, rewrite)\n            if not copy.Export(str(dest)):\n                raise RuntimeError(\'Local USD export failed: \'+str(dest))\n        else:\n            dest.write_bytes(raw.read_bytes())\n        manifest.append({\'url\':url,\'local\':str(dest),\'source_sha256\':hashlib.sha256(raw.read_bytes()).hexdigest(),\'dependencies\':dependencies})\n        return str(dest)\n\n    replacements=[]\n    for owner, field, value, field_path in remote_asset_fields(cfg):\n        target=localize(value)\n        if isinstance(owner, dict):\n            owner[field]=target\n        else:\n            setattr(owner,field,target)\n        replacements.append(field_path)\n    if not replacements:\n        raise RuntimeError(\'No scene assets found; refusing empty localization\')\n    missing=[p for p in mapped.values() if not Path(p).is_file()]\n    if missing:\n        raise RuntimeError(\'Missing localized files: \'+str(missing))\n    remaining=remote_asset_fields(cfg)\n    if remaining:\n        raise RuntimeError(\'Unlocalized configuration assets: \'+str([row[3] for row in remaining]))\n    (report_dir/\'asset_manifest.json\').write_text(json.dumps(manifest,indent=2))\n    print(\'LOCAL_ASSETS_READY\',json.dumps({\'files\':len(mapped),\'scene_fields\':replacements}),flush=True)\n\n\ndef main():\n    out = Path(args.output_dir)\n    out.mkdir(parents=True, exist_ok=False)\n    (out / \'frames\').mkdir()\n    with h5py.File(args.dataset, \'r\') as f:\n        demo = f[\'data\'][args.demo]\n        initial = read_state(demo[\'initial_state\'])\n        initial[\'rigid_object\'][\'object\'][\'root_pose\'][0,0] += args.dx_mm/1000.\n        initial[\'rigid_object\'][\'object\'][\'root_pose\'][0,1] += args.dy_mm/1000.\n        expected_eef = demo[\'obs/eef_pos\'][0]\n    # Check the actual math implementation, not only its documentation, before moving.\n    zero = torch.zeros((1, 3), device=args.device)\n    identity = torch.tensor([[0., 0., 0., 1.]], device=args.device)\n    x90 = torch.tensor([[2**-.5, 0., 0., 2**-.5]], device=args.device)\n    _, probe = compute_pose_error(zero, identity, zero, x90, rot_error_type=\'axis_angle\')\n    torch.testing.assert_close(probe, torch.tensor([[np.pi/2, 0., 0.]], device=args.device), atol=1e-5, rtol=1e-5)\n    print(\'[CONVENTION] installed compute_pose_error uses xyzw: verified\', flush=True)\n\n    cfg = parse_env_cfg(args.task, device=args.device, num_envs=1, use_fabric=True)\n    cfg.seed = args.seed\n    cfg.observations.policy.concatenate_terms = False\n    cfg.recorders = None\n    for name in (\'time_out\', \'object_dropping\', \'success\'):\n        setattr(cfg.terminations, name, None)\n    sensor_offset = cfg.scene.ee_frame.target_frames[0].offset\n    cfg.actions.arm_action.body_offset.pos = tuple(sensor_offset.pos)\n    cfg.actions.arm_action.body_offset.rot = tuple(sensor_offset.rot)\n    scale = float(cfg.actions.arm_action.scale)\n    if scale <= 0:\n        raise ValueError(\'Invalid action scale\')\n    stage_note(\'localizing_assets\')\n    localize_scene_assets(cfg, out)\n    stage_note(\'before_environment_creation\')\n    env = gym.make(args.task, cfg=cfg).unwrapped\n    stage_note(\'after_environment_creation\')\n    training_observations = []\n    records = {k: [] for k in (\'actions\', \'pre_eef\', \'post_eef\', \'pre_quat_xyzw\', \'post_quat_xyzw\',\n                              \'post_cube\', \'gripper_pos\', \'phase\', \'above_error_m\', \'orientation_error_rad\',\n                              \'target_position\', \'ik_sensor_position_error_m\', \'ik_sensor_angle_error_rad\')}\n    try:\n        stage_note(\'before_reset\')\n        obs, _ = env.reset_to(initial, env_ids=None, seed=args.seed, is_relative=True)\n        stage_note(\'after_reset\')\n        def poses():\n            sensor = env.scene[\'ee_frame\'].data\n            return tensor(sensor.target_pos_w)[:, 0].clone(), tensor(sensor.target_quat_w)[:, 0].clone()\n        def cube():\n            return array(tensor(env.scene[\'object\'].data.root_pos_w)[0] - env.scene.env_origins[0])\n        pos_w, quat_w = poses()\n        initial_eef = array(pos_w[0] - env.scene.env_origins[0])\n        initial_cube = cube()\n        reset = {\n            \'eef_first_obs_error_m\': float(np.linalg.norm(array(obs[\'policy\'][\'eef_pos\'])[0] - expected_eef)),\n            \'cube_position_error_m\': float(np.linalg.norm(initial_cube - array(initial[\'rigid_object\'][\'object\'][\'root_pose\'])[0, :3])),\n            \'robot_joint_max_abs_error_rad\': float(np.max(np.abs(array(env.scene[\'robot\'].data.joint_pos)[0] - array(initial[\'articulation\'][\'robot\'][\'joint_position\'])[0])))\n        }\n        if max(reset.values()) > 1e-4:\n            raise RuntimeError(f\'Reset mismatch: {reset}\')\n        action_term = env.action_manager.get_term(\'arm_action\')\n        # x-axis half-turn in WORLD frame, xyzw. Keep the gripper pointing down.\n        target_quat_w = torch.tensor([[1., 0., 0., 0.]], device=env.device)\n        dt = float(cfg.sim.dt) * int(cfg.decimation)\n        required_hold = int(np.ceil(1. / dt))\n        stage_note(\'before_estimator_load\')\n        estimate_cube=load_cube_estimator(args.device)\n        stage_note(\'after_estimator_load\')\n        estimated_cube_positions=[]\n        raw_cube_positions=[]\n        filtered_cube=None\n        stage, stable, close_steps = \'approach\', 0, 0\n        hold_streak = lift_streak = max_hold = max_lift = 0\n        settled_height = None\n        pick_anchor = None\n        success = False\n        first_success_step = None\n        hold_target = None\n        extra_hold_steps = int(np.ceil(3.0/dt))\n        joint_samples = []\n        reason = \'horizon\'\n        with torch.inference_mode():\n            for step in range(args.horizon + extra_hold_steps):\n                pos_w, quat_w = poses()\n                pre = array(pos_w[0] - env.scene.env_origins[0])\n                raw_cube = estimate_cube(capture_obs(obs))\n                raw_cube_positions.append(raw_cube.copy())\n                # Smooth the estimated environmental Cube coordinate, not the moving EEF-relative vector.\n                filtered_cube = raw_cube.copy() if filtered_cube is None else .2*raw_cube + .8*filtered_cube\n                obj = filtered_cube.copy()\n                estimated_cube_positions.append(obj.copy())\n                robot = env.scene[\'robot\'].data\n                root_pos, root_quat = tensor(robot.root_pos_w), tensor(robot.root_quat_w)\n                current_pos_b, current_quat_b = subtract_frame_transforms(root_pos, root_quat, pos_w, quat_w)\n                ik_pos_b, ik_quat_b = action_term._compute_frame_pose()\n                offset_error, angle_error = compute_pose_error(current_pos_b, current_quat_b, ik_pos_b, ik_quat_b,\n                                                               rot_error_type=\'axis_angle\')\n                offset_norm, angle_norm = float(offset_error.norm()), float(angle_error.norm())\n                if offset_norm > 1e-4 or angle_norm > 1e-3:\n                    raise RuntimeError(f\'IK/sensor frame mismatch: {offset_norm} m, {angle_norm} rad\')\n                target = obj + [0., 0., .1]\n                grip = 1.\n                if args.instruction == \'pick up the cube\':\n                    if stage in (\'descend\', \'close\'):\n                        target = obj.copy()\n                    elif stage == \'lift\':\n                        target = pick_anchor + [0., 0., .18]\n                    if stage == \'hold\':\n                        target = hold_target.copy()\n                    if stage in (\'close\', \'lift\', \'hold\'):\n                        grip = -1.\n                target_w = torch.as_tensor(target, dtype=pos_w.dtype, device=env.device)[None] + env.scene.env_origins\n                goal_pos_b, goal_quat_b = subtract_frame_transforms(root_pos, root_quat, target_w, target_quat_w)\n                pos_err, rot_err = compute_pose_error(ik_pos_b, ik_quat_b, goal_pos_b, goal_quat_b,\n                                                       rot_error_type=\'axis_angle\')\n                orientation_error = float(rot_err.norm())\n                delta = torch.cat([bounded(.2 * pos_err, .01), bounded(.2 * rot_err, .08)], dim=-1)\n                action = torch.cat([delta / scale, torch.tensor([[grip]], device=env.device)], dim=-1)\n                phase = stage\n                if step < 13:\n                    action.zero_()\n                    action[:, 6] = 1.\n                    phase = \'settle\'\n                if not torch.isfinite(action).all():\n                    raise RuntimeError(\'Nonfinite teacher action\')\n\n                obs, _, terminated, truncated, _ = env.step(action)\n                joint_samples.append(array(env.scene[\'robot\'].data.joint_pos)[0])\n                post_pos_w, post_quat_w = poses()\n                post = array(post_pos_w[0] - env.scene.env_origins[0])\n                post_cube = cube()\n                fingers = array(obs[\'policy\'][\'gripper_pos\'])[0]\n                error = float(np.linalg.norm(post - (post_cube + [0., 0., .1])))\n                if step == 10:\n                    settled_height = float(post_cube[2])\n                valid_above = error <= .03 and fingers[0] >= .03 and fingers[1] <= -.03\n                hold_streak = hold_streak + 1 if valid_above and step >= 13 else 0\n                max_hold = max(max_hold, hold_streak)\n                lifted = (settled_height is not None and post_cube[2] >= settled_height + .1\n                          and float(action[0, 6]) < 0 and np.linalg.norm(post - post_cube) <= .08)\n                lift_streak = lift_streak + 1 if lifted else 0\n                max_lift = max(max_lift, lift_streak)\n                values = (array(action)[0], pre, post, array(quat_w)[0], array(post_quat_w)[0], post_cube,\n                          fingers, phase, error, orientation_error, target, offset_norm, angle_norm)\n                for key, value in zip(records, values):\n                    records[key].append(value)\n                # Numerical verification; frames are not saved.\n                if step % 25 == 0:\n                    print(\'[STEP]\', step+1, phase, \'above_error_m=\', error, \'rotation_error_rad=\', orientation_error, flush=True)\n                if bool(terminated[0]) or bool(truncated[0]):\n                    reason = \'unexpected_environment_termination\'\n                    break\n                if args.instruction == \'move above the cube\' and hold_streak >= required_hold:\n                    success, reason = True, \'above_position_held\'\n                    break\n                if args.instruction == \'pick up the cube\' and lift_streak >= 10 and first_success_step is None:\n                    first_success_step = step\n                    success = True\n\n                if first_success_step is not None and step >= first_success_step + extra_hold_steps:\n                    reason = \'success_then_3s_teacher_control\'\n                    break\n                if first_success_step is None and step >= args.horizon-1:\n                    reason = \'acquisition_horizon\'\n                    break\n                if step >= 13 and args.instruction == \'pick up the cube\':\n                    reached = np.linalg.norm(post - target) <= .01 and orientation_error <= .1\n                    stable = stable + 1 if reached else 0\n                    if stage == \'approach\' and stable >= 5:\n                        stage, stable = \'descend\', 0\n                    elif stage == \'descend\' and stable >= 5:\n                        stage, stable, close_steps = \'close\', 0, 0\n                        pick_anchor = obj.copy()\n                    elif stage == \'lift\' and stable >= 5:\n                        hold_target=target.copy()\n                        stage=\'hold\'\n                    elif stage == \'close\':\n                        close_steps += 1\n                        if close_steps >= 20:\n                            stage = \'lift\'\n        # Dataset collection is deferred until teacher verification passes.\n        np.savez_compressed(out/\'teacher_trace.npz\', joint_pos=np.asarray(joint_samples), **{k: np.asarray(v) for k, v in records.items()},\n                            initial_eef=initial_eef, initial_cube=initial_cube, instruction=args.instruction)\n        summary = {\n            \'instruction\': args.instruction, \'success\': success, \'stop_reason\': reason,\n            \'teacher_type\': \'official_pose_error_in_robot_frame_bounded_steps\', \'learned_language_policy\': False,\n            \'executed_steps\': len(records[\'actions\']), \'step_dt\': dt, \'reset_check\': reset,\n            \'max_consecutive_above_hold_steps\': max_hold, \'required_above_hold_steps\': required_hold,\n            \'max_consecutive_lift_steps\': max_lift, \'final_above_error_m\': records[\'above_error_m\'][-1],\n            \'final_cube_height_m\': float(records[\'post_cube\'][-1][2]),\n            \'settled_cube_height_m\': settled_height, \'last_phase\': records[\'phase\'][-1],\n            \'settings\': {\'quaternion\': \'xyzw, runtime checked\', \'target_quaternion_world\': [1,0,0,0],\n                         \'hand_offset_m\': list(sensor_offset.pos), \'scale\': scale, \'gain\': .2,\n                         \'max_translation_increment_m\': .01, \'max_rotation_increment_rad\': .08,\n                         \'settle_steps\': 13},\n            \'limitations\': [\'Teacher diagnostic only; not VLA success.\',\n                            \'Pick uses lift proxy, not contact-force validation.\',\n                            \'Changes convention, frame alignment, desired orientation and gains together; not a single-variable causal test.\'],\n            \'script_sha256\': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n            \'frames\': str(out/\'frames\')}\n        (out/\'summary.json\').write_text(json.dumps(summary, indent=2), encoding=\'utf-8\')\n        print(json.dumps(summary, indent=2), flush=True)\n        print(\'SUMMARY=\' + str(out/\'summary.json\'), flush=True)\n        trace_cube=np.asarray(records[\'post_cube\'])\n        trace_actions=np.asarray(records[\'actions\'])\n        horizontal=np.linalg.norm(trace_cube[:,:2]-trace_cube[10,:2],axis=1)*1000\n        threshold=(settled_height+.1)*1000\n        closed=np.flatnonzero(trace_actions[:,6]<0)\n        first_close=int(closed[0]) if len(closed) else None\n        first=first_success_step\n        pick_xy=float(horizontal[first_close:first+1].max()) if first is not None and first_close is not None else None\n        pick_pass=bool(first is not None and pick_xy is not None and pick_xy<=50)\n        complete=first is not None and len(trace_cube)-1-first>=extra_hold_steps\n        hold=False\n        min_height=None\n        hold_xy=None\n        if first is not None and len(trace_cube)>first+1:\n            heights=trace_cube[first+1:,2]*1000\n            min_height=float(heights.min())\n            hold_xy=float(horizontal[first+1:].max())\n            hold=bool(complete and np.all(heights>=threshold) and hold_xy<=50)\n        robot=env.scene[\'robot\']\n        ids=[robot.joint_names.index(\'panda_joint\'+str(i)) for i in range(1,8)]\n        bounds=array(robot.data.joint_pos_limits)[0,ids]\n        joints=np.asarray(joint_samples)[:,ids]\n        margins=np.minimum(joints-bounds[:,0],bounds[:,1]-joints)\n        finite=all(np.isfinite(np.asarray(records[k])).all() for k in (\'actions\',\'post_eef\',\'post_cube\')) and np.isfinite(joints).all()\n        margin=float(margins.min())\n        phases=np.asarray(records[\'phase\'])\n        target_error=np.linalg.norm(np.asarray(records[\'post_eef\'])-np.asarray(records[\'target_position\']),axis=1)*1000\n        phase_best={phase:float(target_error[phases==phase].min()) for phase in sorted(set(records[\'phase\']))}\n        result={\'offset_mm\':[args.dx_mm,args.dy_mm], \'teacher_only\':False,\n                \'pick_pass\':pick_pass,\'hold_3s_pass\':hold,\'first_success_step\':first,\n                \'first_close_step\':first_close,\'samples\':len(trace_cube),\'last_phase\':records[\'phase\'][-1],\n                \'stop_reason\':reason,\'required_height_mm\':threshold,\n                \'maximum_cube_height_after_settle_mm\':float(trace_cube[10:,2].max()*1000),\n                \'hold_minimum_height_mm\':min_height,\'pick_maximum_xy_mm\':pick_xy,\n                \'hold_maximum_xy_mm\':hold_xy,\'minimum_arm_joint_margin_rad\':margin,\n                \'phase_best_position_error_mm\':phase_best,\n                \'pass\':bool(pick_pass and hold and finite and margin>=-.001),\n                \'dataset_collected\':False,\'training_performed\':False,\'result_directory\':str(out)}\n        result.update(oracle_state=False,learned_policy=False,learned_perception=True,structured_controller=True,hold_target_fixed=True,hold_target_source="existing_lift_goal")\n        np.save(out/\'estimated_cube_positions.npy\',np.asarray(estimated_cube_positions))\n        np.save(out/\'raw_estimated_cube_positions.npy\',np.asarray(raw_cube_positions))\n        result[\'perception_filter\']=\'environment_position_ema_alpha_0.2\'\n        (out/\'teacher_result.json\').write_text(json.dumps(result,indent=2))\n        print(\'TEACHER_RESULT\',json.dumps(result),flush=True)\n\n    except BaseException:\n        import traceback\n        detail=traceback.format_exc()\n        Path(args.output_dir).mkdir(parents=True,exist_ok=True)\n        (Path(args.output_dir)/\'worker_exception.txt\').write_text(detail)\n        print(detail,flush=True)\n        raise\n    finally:\n        env.close()\n\n\nif __name__ == \'__main__\':\n    import traceback,sys,atexit\n    diagnostic_directory=Path(args.output_dir).parent/(Path(args.output_dir).name+\'_diagnostics\')\n    diagnostic_directory.mkdir(parents=True,exist_ok=True)\n    def stage_note(stage):\n        (diagnostic_directory/\'startup_stage.txt\').write_text(stage)\n        print(\'STARTUP_STAGE\',stage,flush=True)\n    def exit_note():\n        (diagnostic_directory/\'python_exit_reached.txt\').write_text(\'atexit reached\')\n    atexit.register(exit_note)\n    stage_note(\'enter_main\')\n    try:\n        main()\n        stage_note(\'main_returned\')\n    except BaseException:\n        detail=traceback.format_exc()\n        (diagnostic_directory/\'worker_exception.txt\').write_text(detail)\n        print(\'OUTER_EXCEPTION\\n\'+detail,file=sys.stderr,flush=True)\n        raise\n    finally:\n        app.close()\n'

def main():
    root=Path('/workspace/step4')
    folder=Path(tempfile.mkdtemp(prefix='visual_random30_',dir=root))
    print('RUN_DIRECTORY',folder,flush=True)
    script=folder/'evaluate.py';script.write_text(SOURCE)
    previous=root/'visual_structured_grid_mswr833h'
    assert hashlib.sha256((previous/'evaluate.py').read_text().encode()).hexdigest()=='bac47d55d5d822a70686a899a38da1e9c070cd328a68fe2866c3c2d9d004fd6f', 'Unexpected baseline controller'
    reports=[]
    positions=[(-2.12, 15.26), (-21.914, -6.215), (-24.981, -19.628), (-4.286, 24.037), (-18.254, 4.408)]
    checkpoint=root/'spatial_cube_oracle30_refit_n1yvrn5i/candidate.pt'
    checkpoint_sha256=hashlib.sha256(checkpoint.read_bytes()).hexdigest()
    (folder/'protocol.json').write_text(json.dumps(dict(oracle_state=False,learned_policy=False,learned_perception=True,
        evaluation_scope='five new positions sampled uniformly in XY +/-30mm before evaluation; model frozen',position_sampling_seed=2026100530,positions=positions,reference_run=str(previous),checkpoint_sha256=checkpoint_sha256,seed=2058,horizon=1300,perception_filter='EMA alpha=.2 in environment coordinates; reset every trial',position_threshold_m=.01,required_stable_steps=5,hold_seconds=3,
        hold_target='existing lift goal and original downward orientation'),indent=2))
    paths=[root/'.runtime_packages',root/'python_packages',Path('/isaac-sim/extsDeprecated/omni.isaac.ml_archive/pip_prebundle'),root/'baseline_inputs/environment/runtime_packages',root/'baseline_inputs/runtime/code']
    source=Path('/workspace/IsaacLab-develop/source')
    paths+=sorted(p for p in source.iterdir() if p.is_dir() and (p/p.name/'__init__.py').is_file())
    env=os.environ.copy();env['PYTHONUNBUFFERED']='1';env['CUBLAS_WORKSPACE_CONFIG']=':4096:8'
    env['PYTHONPATH']=os.pathsep.join([str(p) for p in paths if p.is_dir()]+[env.get('PYTHONPATH','')])
    env['LD_LIBRARY_PATH']='/workspace/step3/ngx_runtime_580.65.06_cgbe5u2a/lib:'+env.get('LD_LIBRARY_PATH','')
    preflight=folder/'preflight.py';preflight.write_text("import torch,numpy as np,h5py\nfrom pathlib import Path\ndef load_cube_estimator(device):\n    from torch import nn\n    from torchvision.models import resnet18\n    path=Path('/workspace/step4/spatial_cube_oracle30_refit_n1yvrn5i/candidate.pt')\n    ck=torch.load(path,map_location='cpu',weights_only=False)\n    assert ck['format']=='spatial_cube_estimator_v1'\n    net=resnet18(weights=None)\n    encoder=nn.Sequential(*list(net.children())[:6],nn.AdaptiveAvgPool2d((5,5))).to(device).eval()\n    encoder.load_state_dict(ck['encoder_state'],strict=True)\n    head=nn.Sequential(nn.Linear(ck['input_dim'],256),nn.GELU(),nn.Linear(256,64),nn.GELU(),nn.Linear(64,3)).to(device).eval()\n    head.load_state_dict(ck['head_state'],strict=True)\n    fm=ck['feature_mean'].to(device);fs=ck['feature_scale'].to(device)\n    ym=ck['target_mean'].to(device);ys=float(ck['target_scale'])\n    mean=torch.tensor([.485,.456,.406],device=device)[None,:,None,None]\n    std=torch.tensor([.229,.224,.225],device=device)[None,:,None,None]\n    def predict(captured):\n        q=captured['eef_quat'].copy()\n        if q[3]<0:q=-q\n        state=np.concatenate([captured['eef_pos'],q,captured['gripper_pos']])\n        with torch.inference_mode():\n            maps=[]\n            for key in ('table_cam','wrist_cam'):\n                im=torch.tensor(captured[key],device=device).permute(2,0,1).float()[None]/255\n                maps.append(encoder((im-mean)/std).flatten(1))\n            feature=torch.cat(maps+[torch.tensor(state,device=device,dtype=torch.float32)[None]],dim=1)\n            relative=head((feature-fm)/fs)*ys+ym\n        result=captured['eef_pos']+relative[0].cpu().numpy()\n        assert np.isfinite(result).all()\n        return result\n    return predict\n\n\npredict=load_cube_estimator('cuda:0')\nimport json\nmanifest=json.loads(Path('/workspace/step4/cube_vision_full_data_5a28urn1/manifest.json').read_text())\nwith h5py.File(manifest['episodes'][0]['dataset_file'],'r') as h:\n    obs=h['data/demo_0/obs']\n    for i in range(3):predict({k:obs[k][i] for k in ('table_cam','wrist_cam','eef_pos','eef_quat','gripper_pos')})\nprint('VISION_RUNTIME_PREFLIGHT_OK',flush=True)\n")
    subprocess.run([sys.executable,'-u',str(preflight)],env=env,check=True)
    try:
        for index,(dx,dy) in enumerate(positions):
            assert hashlib.sha256(checkpoint.read_bytes()).hexdigest()==checkpoint_sha256
            name=f'trial_{index+1:02d}';out=folder/name
            command=['timeout','--kill-after=30s','1200s','/workspace/IsaacLab-develop/isaaclab.sh','-p',str(script),
                '--instruction','pick up the cube','--dataset',str(root/'baseline_inputs/datasets/lift_robomimic_language.hdf5'),
                '--device','cuda:0','--seed','2058','--horizon','1300','--dx-mm',str(dx),'--dy-mm',str(dy),'--output-dir',str(out)]
            with (folder/(name+'.log')).open('w') as log:
                proc=subprocess.Popen(command,cwd='/workspace/IsaacLab-develop',env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)
                try:
                    for line in proc.stdout:
                        log.write(line);log.flush()
                        if any(k in line for k in ('[STEP]','Traceback','Error:','STARTUP_STAGE','OUTER_EXCEPTION','LOCAL_ASSETS_READY')):print(line.rstrip()[:250],flush=True)
                    code=proc.wait()
                except BaseException:
                    proc.terminate();proc.wait();raise
            result=out/'teacher_result.json'
            (folder/(name+'_exit.json')).write_text(json.dumps(dict(returncode=code,result_exists=result.exists())))
            print('PROCESS_EXIT',code,flush=True)
            if code or not result.exists():
                error=out/'worker_exception.txt'
                if not error.exists():error=out.parent/(out.name+'_diagnostics')/'worker_exception.txt'
                if error.exists():print(error.read_text()[-4000:])
                stage_file=out.parent/(out.name+'_diagnostics')/'startup_stage.txt'
                print('LAST_STARTUP_STAGE',stage_file.read_text() if stage_file.exists() else 'unavailable',flush=True)
                raise RuntimeError('Incomplete diagnostic; see '+str(folder/(name+'.log')))
            r=json.loads(result.read_text());r['trial']=index+1;reports.append(r)
            assert hashlib.sha256(checkpoint.read_bytes()).hexdigest()==checkpoint_sha256
            (folder/'results.json').write_text(json.dumps(reports,indent=2))
            print('POSITION_DONE',dx,dy,'PASS' if r['pass'] else 'FAIL',flush=True)
    finally:
        lines=['VISUAL_RANDOM30_SUMMARY','trial | dx_mm dy_mm | pass | first_close | first_success | hold_min_height_mm | hold_max_xy_mm']
        for r in reports:
            def fmt(v):return '-' if v is None else f'{v:.2f}'
            lines.append(f"{r['trial']} | {positions[r['trial']-1][0]} {positions[r['trial']-1][1]} | {r['pass']} | {r.get('first_close_step')} | {r.get('first_success_step')} | {fmt(r.get('hold_minimum_height_mm'))} | {fmt(r.get('hold_maximum_xy_mm'))}")
        lines.append(f"TOTAL {sum(r['pass'] for r in reports)}/{len(reports)}; oracle_state=False; learned_policy=False; learned_perception=True")
        lines.append('RESULT_DIRECTORY '+str(folder))
        text='\n'.join(lines)+'\n';(folder/'summary.txt').write_text(text);print(text,flush=True)

if __name__=='__main__':main()
